lemma SqMono(a: int, b: int)
  requires 0 <= a <= b
  ensures a * a <= b * b
{
  assert (b - a) * (b + a) == b * b - a * a;
  assert (b - a) * (b + a) >= 0;
}

method {:isolate_assertions} Solve(n: int) returns (output: string, ghost steps: nat)
  ensures steps <= n * n + 12 * n + 70
{
  steps := 1;
  var x := 0;
  var i := 1;
  while i <= n
    invariant 1 <= i
    invariant i > 1 ==> i <= n + 2
    invariant steps <= i * i + 4 * i + 5
    decreases n - i
  {
    var iOld := i;
    var s0 := steps;
    var c := 0;
    var j := 1;
    while j <= i
      invariant 1 <= j <= i + 1
      invariant steps <= s0 + 2 * (j - 1)
      decreases i - j
