  var l := 0;
  var h := |res| - 1;
  var ans := -1;
  ghost var base2 := steps;
  ghost var cnt2 := 0;
  ghost var span0 := h - l;
  while l <= h
    invariant 0 <= l
    invariant h <= |res| - 1
    invariant h - l <= span0 - cnt2
    invariant cnt2 <= span0 + 1
    invariant steps <= base2 + 2 * cnt2
    decreases h - l
  {
    var mid := l + (h - l) / 2;
    ghost var oldSpan := h - l;
    if res[mid] + b * (c - 1) < a * c {
      ans := mid;
      l := mid + 1;
      assert h - l <= oldSpan - 1;
    } else {
      h := mid - 1;
      assert h - l <= oldSpan - 1;
    }
    cnt2 := cnt2 + 1;
    steps := steps + 2;
  }
  assert cnt2 <= span0 + 1;
  assert span0 <= |res|;
  assert cnt2 <= |res| + 1;
  assert |res| <= a * c + 2;
  output := IntToString(ans + 1);
  steps := steps + |output| + 2;
}

