  assert forall k :: 0 <= k < n ==> r[k] == intervals[k][1];
  assert l1 != -1;
  assert r1 != -1;
  var l_1 := l[..l1] + l[l1+1..];
  var r_1 := r[..l1] + r[l1+1..];
  var l_2 := l[..r1] + l[r1+1..];
  var r_2 := r[..r1] + r[r1+1..];
  steps := steps + 4 * (2 + n);
  var opt1 := MinSeq(r_1) - MaxSeq(l_1);
  var opt2 := MinSeq(r_2) - MaxSeq(l_2);
