method {:isolate_assertions} Solve(n: int, a_list: seq<int>) returns (output: string, ghost steps: nat)
  requires n == |a_list|
  requires n >= 1
  ensures steps <= 2 * n * (CeilLog2(n) + 1) + 8 * n + |output| + 10
