  ghost var base1 := steps;
  while x < n && !doneFlag
    invariant 1 <= x <= n
    invariant steps <= base1 + 4 * (x - 1) + (if doneFlag then 4 * n else 0)
    decreases n - x
  {
    if a_list[x - 1] > a_list[x] {
      d := 1;
      if sortedA == a_list[x..] + a_list[..x] {
        ans := n - x;
      } else {
        ans := -1;
      }
      doneFlag := true;
      steps := steps + 4 * n;
